screenPanels.initJs:
function(container, apiUrl, tables) {
  const form = container.querySelector('#purchase-form');
  const quantityInput = container.querySelector('input[name="quantity"]');
  const unitPriceInput = container.querySelector('input[name="unit_price"]');
  const totalAmountDiv = container.querySelector('#total-amount');
  const cancelBtn = container.querySelector('#cancel-btn');
  const saveBtn = container.querySelector('#save-btn');
  const recentTbody = container.querySelector('#recent-tbody');
  const deleteModal = container.querySelector('#delete-modal');
  const deleteCancelBtn = container.querySelector('#delete-cancel-btn');
  const deleteConfirmBtn = container.querySelector('#delete-confirm-btn');

  let recordToDelete = null;

  // 合計金額の自動計算
  function updateTotalAmount() {
    const qty = parseFloat(quantityInput.value) || 0;
    const price = parseFloat(unitPriceInput.value) || 0;
    const total = Math.round(qty * price);
    totalAmountDiv.textContent = `¥${total.toLocaleString()}`;
  }

  quantityInput.addEventListener('input', updateTotalAmount);
  unitPriceInput.addEventListener('input', updateTotalAmount);

  // 最近の登録記録を読み込み
  async function loadRecentRecords() {
    const records = await window.aivicApi.list(4); // 購入記録テーブルのインデックス
    if (!records || records.length === 0) {
      recentTbody.innerHTML = `
        <tr style="border-bottom: 1px solid var(--border);">
          <td colspan="5" style="padding: 16px; text-align: center; color: var(--text-muted);">
            登録記録がありません
          </td>
        </tr>
      `;
      return;
    }

    // 最新10件を表示
    const recent = records.slice(0, 10);
    recentTbody.innerHTML = recent.map(record => `
      <tr style="border-bottom: 1px solid var(--border);" data-id="${record.id}">
        <td style="padding: 8px; color: var(--text);">
          ${new Date(record.purchase_date).toLocaleDateString('ja-JP')}
        </td>
        <td style="padding: 8px; color: var(--text);">
          ${record.product_name || '—'}
        </td>
        <td style="padding: 8px; color: var(--text);">
          ${record.category || '—'}
        </td>
        <td style="padding: 8px; text-align: right; color: var(--text); font-weight: 500;">
          ¥${(record.purchase_amount || 0).toLocaleString()}
        </td>
        <td style="padding: 8px; text-align: center;">
          <button
            type="button"
            class="delete-btn"
            data-id="${record.id}"
            style="padding: 4px 8px; font-size: 11px; border-radius: 3px; background: transparent; border: 1px solid rgba(139, 111, 71, 0.25); color: var(--text-muted); cursor: pointer; transition: all 0.2s;"
          >
            削除
          </button>
        </td>
      </tr>
    `).join('');

    // 削除ボタンのイベントリスナー
    container.querySelectorAll('.delete-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        recordToDelete = e.target.dataset.id;
        deleteModal.style.display = 'flex';
      });
    });
  }

  // フォーム送信
  form.addEventListener('submit', async (e) => {
    e.preventDefault();

    const formData = {
      purchase_date: form.elements.purchase_date.value,
      supermarket_id: form.elements.supermarket_id.value,
      distributor_id: form.elements.distributor_id.value,
      product_name: form.elements.product_name.value,
      category: form.elements.category.value,
      quantity: parseFloat(form.elements.quantity.value) || 0,
      unit: form.elements.unit.value,
      unit_price: parseInt(form.elements.unit_price.value) || 0,
      purchase_amount: Math.round((parseFloat(form.elements.quantity.value) || 0) * (parseInt(form.elements.unit_price.value) || 0)),
      expiry_date: form.elements.expiry_date.value || null,
      stock_quantity: parseFloat(form.elements.stock_quantity.value) || 0,
      memo: form.elements.memo.value || null,
    };

    const saved = await window.aivicApi.save(4, formData); // 購入記録テーブル
    if (saved) {
      // 保存成功後、最近の記録を再読み込み
      await loadRecentRecords();
      // フォームをリセット
      form.reset();
      updateTotalAmount();
    }
  });

  // キャンセルボタン
  cancelBtn.addEventListener('click', () => {
    window.showScreen('scr-1783679170666');
  });

  // 削除確認ダイアログ
  deleteCancelBtn.addEventListener('click', () => {
    deleteModal.style.display = 'none';
    recordToDelete = null;
  });

  deleteConfirmBtn.addEventListener('click', async () => {
    if (recordToDelete) {
      await window.aivicApi.delete(4, recordToDelete);
      deleteModal.style.display = 'none';
      recordToDelete = null;
      await loadRecentRecords();
    }
  });

  // Escキーでダイアログを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && deleteModal.style.display !== 'none') {
      deleteModal.style.display = 'none';
      recordToDelete = null;
    }
  });

  // 初期化
  loadRecentRecords();
  updateTotalAmount();
}

function(container, apiUrl, tables) {
  const state = {
    currentMonth: new Date().toISOString().slice(0, 7),
    currentTab: 'category',
    budgetData: null,
    analysisData: null,
    timeseriesData: []
  };

  // ===== DOM Elements =====
  const monthInput = container.querySelector('[data-testid="analysis-month"]');
  const tabButtons = container.querySelectorAll('.tab-btn');
  const analysisChart = container.querySelector('#analysis-chart');
  const timeseriesChart = container.querySelector('#timeseries-chart');
  const analysisTbody = container.querySelector('#analysis-tbody');
  const backButton = container.querySelector('[data-testid="back-button"]');
  const exportButton = container.querySelector('[data-testid="export-csv-button"]');
  const recordButton = container.querySelector('[data-testid="record-improvement-button"]');
  const improvementModal = container.querySelector('#improvement-modal');
  const closeModalBtn = container.querySelector('#close-improvement-modal');
  const cancelStrategyBtn = container.querySelector('#cancel-strategy');
  const saveStrategyBtn = container.querySelector('#save-strategy-button');

  // ===== Initialize =====
  monthInput.value = state.currentMonth;
  tabButtons[0].style.borderBottomColor = 'var(--primary)';

  // ===== Event Listeners =====
  monthInput.addEventListener('change', (e) => {
    state.currentMonth = e.target.value;
    loadAnalysisData();
  });

  tabButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      tabButtons.forEach(b => b.style.borderBottomColor = 'transparent');
      btn.style.borderBottomColor = 'var(--primary)';
      state.currentTab = btn.dataset.tab;
      renderAnalysisTable();
      renderChart();
    });
  });

  backButton.addEventListener('click', () => {
    window.showScreen("scr-1783679155883");
  });

  exportButton.addEventListener('click', exportToCSV);
  recordButton.addEventListener('click', () => {
    improvementModal.style.display = 'flex';
  });

  closeModalBtn.addEventListener('click', closeModal);
  cancelStrategyBtn.addEventListener('click', closeModal);
  saveStrategyBtn.addEventListener('click', saveStrategy);

  improvementModal.addEventListener('click', (e) => {
    if (e.target === improvementModal) closeModal();
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && improvementModal.style.display === 'flex') {
      closeModal();
    }
  });

  // ===== Functions =====
  async function loadAnalysisData() {
    try {
      // 月次食費予算を取得
      const budgets = await window.aivicApi.list(0); // 月次食費予算テーブル
      state.budgetData = budgets?.find(b => b.年月 === state.currentMonth);

      // 超過要因分析データを取得
      const analyses = await window.aivicApi.list(11); // 超過要因分析テーブル
      state.analysisData = analyses?.filter(a => a.分析対象年月 === state.currentMonth) || [];

      // 時系列データを取得（過去12ヶ月）
      const allAnalyses = await window.aivicApi.list(11);
      const last12Months = getLast12Months();
      state.timeseriesData = last12Months.map(month => {
        const monthAnalyses = allAnalyses?.filter(a => a.分析対象年月 === month) || [];
        const totalExcess = monthAnalyses.reduce((sum, a) => sum + (a.超過額 || 0), 0);
        return { month, totalExcess };
      });

      updateKPIs();
      renderAnalysisTable();
      renderChart();
      renderTimeseriesChart();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  function updateKPIs() {
    const budgetEl = container.querySelector('[data-testid="kpi-budget"]');
    const actualEl = container.querySelector('[data-testid="kpi-actual"]');
    const excessEl = container.querySelector('[data-testid="kpi-excess"]');
    const rateEl = container.querySelector('[data-testid="kpi-excess-rate"]');

    const budget = state.budgetData?.予算額 || 0;
    const actual = state.analysisData?.reduce((sum, a) => sum + (a.実績額 || 0), 0) || 0;
    const excess = actual - budget;
    const rate = budget > 0 ? Math.round((excess / budget) * 1000) / 10 : 0;

    budgetEl.textContent = `¥${budget.toLocaleString()}`;
    actualEl.textContent = `¥${actual.toLocaleString()}`;
    excessEl.textContent = `¥${excess.toLocaleString()}`;
    rateEl.textContent = `${rate}%`;
  }

  function renderAnalysisTable() {
    const data = getFilteredData();
    analysisTbody.innerHTML = '';

    if (data.length === 0) {
      analysisTbody.innerHTML = '<tr style="background: var(--bg-card);"><td colspan="5" style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">データがありません</td></tr>';
      return;
    }

    data.forEach((row, idx) => {
      const tr = document.createElement('tr');
      tr.style.background = idx % 2 === 0 ? 'var(--bg-card)' : 'var(--bg-main)';
      tr.innerHTML = `
        <td style="padding: 6px 8px; border-bottom: 1px solid var(--border); color: var(--text);">${row.name}</td>
        <td style="padding: 6px 8px; border-bottom: 1px solid var(--border); color: var(--text); text-align: right;">¥${(row.budget || 0).toLocaleString()}</td>
        <td style="padding: 6px 8px; border-bottom: 1px solid var(--border); color: var(--text); text-align: right;">¥${(row.actual || 0).toLocaleString()}</td>
        <td style="padding: 6px 8px; border-bottom: 1px solid var(--border); color: #d97706; text-align: right; font-weight: 600;">¥${(row.excess || 0).toLocaleString()}</td>
        <td style="padding: 6px 8px; border-bottom: 1px solid var(--border); color: #d97706; text-align: right; font-weight: 600;">${row.rate}%</td>
      `;
      analysisTbody.appendChild(tr);
    });
  }

  function renderChart() {
    const ctx = analysisChart.getContext('2d');
    const data = getFilteredData();

    // Clear canvas
    ctx.clearRect(0, 0, analysisChart.width, analysisChart.height);

    const width = analysisChart.width;
    const height = analysisChart.height;
    const padding = 40;
    const chartWidth = width - 2 * padding;
    const chartHeight = height - 2 * padding;

    // Draw axes
    ctx.strokeStyle = '#d4a574';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // Draw bars (超過額)
    const maxExcess = Math.max(...data.map(d => d.excess || 0), 1);
    const barWidth = chartWidth / (data.length * 1.5);
    const barGap = barWidth * 0.5;

    data.forEach((row, idx) => {
      const x = padding + (idx * (barWidth + barGap));
      const barHeight = (row.excess / maxExcess) * chartHeight;
      const y = height - padding - barHeight;

      ctx.fillStyle = '#d97706';
      ctx.fillRect(x, y, barWidth, barHeight);

      // Label
      ctx.fillStyle = '#2d1810';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(row.name.slice(0, 4), x + barWidth / 2, height - padding + 16);
    });
  }

  function renderTimeseriesChart() {
    const ctx = timeseriesChart.getContext('2d');
    ctx.clearRect(0, 0, timeseriesChart.width, timeseriesChart.height);

    const width = timeseriesChart.width;
    const height = timeseriesChart.height;
    const padding = 30;
    const chartWidth = width - 2 * padding;
    const chartHeight = height - 2 * padding;

    // Draw axes
    ctx.strokeStyle = '#d4a574';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // Draw line
    const maxExcess = Math.max(...state.timeseriesData.map(d => d.totalExcess || 0), 1);
    ctx.strokeStyle = '#d97706';
    ctx.lineWidth = 2;
    ctx.beginPath();

    state.timeseriesData.forEach((row, idx) => {
      const x = padding + (idx / (state.timeseriesData.length - 1)) * chartWidth;
      const y = height - padding - (row.totalExcess / maxExcess) * chartHeight;

      if (idx === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // Draw points
    ctx.fillStyle = '#d97706';
    state.timeseriesData.forEach((row, idx) => {
      const x = padding + (idx / (state.timeseriesData.length - 1)) * chartWidth;
      const y = height - padding - (row.totalExcess / maxExcess) * chartHeight;
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  function getFilteredData() {
    if (state.currentTab === 'category') {
      return state.analysisData.map(a => ({
        name: a.食材カテゴリ,
        budget: a.予算額,
        actual: a.実績額,
        excess: a.超過額,
        rate: a.超過率
      }));
    } else if (state.currentTab === 'vendor') {
      // 購入先別に集計（簡略版）
      const grouped = {};
      state.analysisData.forEach(a => {
        const key = a.主要因 || '不明';
        if (!grouped[key]) grouped[key] = { budget: 0, actual: 0, excess: 0 };
        grouped[key].budget += a.予算額;
        grouped[key].actual += a.実績額;
        grouped[key].excess += a.超過額;
      });
      return Object.entries(grouped).map(([name, data]) => ({
        name,
        budget: data.budget,
        actual: data.actual,
        excess: data.excess,
        rate: data.budget > 0 ? Math.round((data.excess / data.budget) * 1000) / 10 : 0
      }));
    } else {
      // 食材別（簡略版）
      return state.analysisData.slice(0, 5).map(a => ({
        name: a.食材カテゴリ,
        budget: a.予算額,
        actual: a.実績額,
        excess: a.超過額,
        rate: a.超過率
      }));
    }
  }

  function getLast12Months() {
    const months = [];
    const now = new Date(state.currentMonth + '-01');
    for (let i = 11; i >= 0; i--) {
      const d = new Date(now);
      d.setMonth(d.getMonth() - i);
      months.push(d.toISOString().slice(0, 7));
    }
    return months;
  }

  function exportToCSV() {
    const data = getFilteredData();
    const headers = ['項目', '予算額', '実績額', '超過額', '超過率'];
    const rows = data.map(d => [d.name, d.budget, d.actual, d.excess, `${d.rate}%`]);

    const csv = '\uFEFF' + [headers, ...rows].map(row => row.map(cell => `"${cell}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `超過要因分析_${state.currentMonth}.csv`;
    link.click();
  }

  function closeModal() {
    improvementModal.style.display = 'none';
    container.querySelector('#strategy-name').value = '';
    container.querySelector('#strategy-description').value = '';
    container.querySelector('#strategy-category').value = '';
  }

  async function saveStrategy() {
    const name = container.querySelector('#strategy-name').value.trim();
    const description = container.querySelector('#strategy-description').value.trim();
    const category = container.querySelector('#strategy-category').value;

    if (!name || !description || !category) {
      alert('すべてのフィールドを入力してください');
      return;
    }

    try {
      await window.aivicApi.save(12, {
        施策名: name,
        施策説明: description,
        実施開始日: new Date().toISOString(),
        施策前食費合計: 0,
        施策後食費合計: 0,
        削減額: 0,
        削減率: 0,
        比較期間日数: 0,
        施策ステータス: '進行中'
      });
      closeModal();
      alert('施策を記録しました');
    } catch (error) {
      console.error('保存エラー:', error);
      alert('保存に失敗しました');
    }
  }

  // Initial load
  loadAnalysisData();
}

function(container, apiUrl, tables) {
  // テーブルインデックスの定義
  const TABLE_INVENTORY = 0;      // 在庫データ
  const TABLE_PRICE = 1;          // 価格データ
  const TABLE_SUPERMARKET = 2;    // スーパー
  const TABLE_DISTRIBUTOR = 3;    // 流通業者
  const TABLE_INGREDIENT = 4;     // 食材

  // DOM 要素の取得
  const searchInput = container.querySelector('[data-testid="search-ingredient"]');
  const categoryFilter = container.querySelector('[data-testid="category-filter"]');
  const supermarketFilter = container.querySelector('[data-testid="supermarket-filter"]');
  const searchBtn = container.querySelector('[data-testid="search-btn"]');
  const syncInventoryBtn = container.querySelector('[data-testid="sync-inventory-btn"]');
  const syncPriceBtn = container.querySelector('[data-testid="sync-price-btn"]');
  const refreshBtn = container.querySelector('[data-testid="refresh-btn"]');
  const backBtn = container.querySelector('[data-testid="back-btn"]');
  const inventoryTbody = container.querySelector('#inventory-tbody');
  const priceTbody = container.querySelector('#price-tbody');
  const discountTbody = container.querySelector('#discount-tbody');
  const inventoryCountEl = container.querySelector('[data-testid="inventory-count"]');
  const priceCountEl = container.querySelector('[data-testid="price-count"]');
  const discountCountEl = container.querySelector('[data-testid="discount-count"]');
  const lastSyncTimeEl = container.querySelector('#last-sync-time');

  // グローバル状態
  let allInventory = [];
  let allPrices = [];
  let allIngredients = [];
  let allSupermarkets = [];

  // ===== データ取得関数 =====
  async function loadData() {
    try {
      // 在庫データ取得
      const inventoryData = await window.aivicApi.list(TABLE_INVENTORY);
      allInventory = inventoryData || [];

      // 価格データ取得
      const priceData = await window.aivicApi.list(TABLE_PRICE);
      allPrices = priceData || [];

      // 食材マスタ取得
      const ingredientData = await window.aivicApi.list(TABLE_INGREDIENT);
      allIngredients = ingredientData || [];

      // スーパーマスタ取得
      const supermarketData = await window.aivicApi.list(TABLE_SUPERMARKET);
      allSupermarkets = supermarketData || [];

      // KPI 更新
      updateKPIs();

      // 初期表示
      renderInventoryList();
      renderPriceComparison();
      renderDiscounts();

      // 最終同期時刻を更新
      const now = new Date();
      lastSyncTimeEl.textContent = now.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
    } catch (error) {
      console.error('データ取得エラー:', error);
    }
  }

  // ===== KPI 更新 =====
  function updateKPIs() {
    inventoryCountEl.textContent = allInventory.length;
    priceCountEl.textContent = allPrices.length;

    // 割引商品数（割引率 > 0）
    const discountCount = allPrices.filter(p => p.割引率 && p.割引率 > 0).length;
    discountCountEl.textContent = discountCount;
  }

  // ===== フィルター適用 =====
  function getFilteredData() {
    const searchTerm = searchInput.value.toLowerCase();
    const selectedCategory = categoryFilter.value;
    const selectedSupermarket = supermarketFilter.value;

    return allInventory.filter(inv => {
      const ingredient = allIngredients.find(i => i.食材ID === inv.食材ID);
      if (!ingredient) return false;

      const matchesSearch = !searchTerm || ingredient.食材名.toLowerCase().includes(searchTerm);
      const matchesCategory = !selectedCategory || ingredient.カテゴリ === selectedCategory;

      return matchesSearch && matchesCategory;
    });
  }

  function getFilteredPrices() {
    const searchTerm = searchInput.value.toLowerCase();
    const selectedCategory = categoryFilter.value;
    const selectedSupermarket = supermarketFilter.value;

    return allPrices.filter(price => {
      const ingredient = allIngredients.find(i => i.食材ID === price.食材ID);
      if (!ingredient) return false;

      const matchesSearch = !searchTerm || ingredient.食材名.toLowerCase().includes(searchTerm);
      const matchesCategory = !selectedCategory || ingredient.カテゴリ === selectedCategory;
      const matchesSupermarket = !selectedSupermarket || price.スーパーID === selectedSupermarket;

      return matchesSearch && matchesCategory && matchesSupermarket;
    });
  }

  // ===== 在庫一覧レンダリング =====
  function renderInventoryList() {
    const filtered = getFilteredData();
    inventoryTbody.innerHTML = '';

    if (filtered.length === 0) {
      inventoryTbody.innerHTML = '<tr style="background: var(--bg-main);"><td colspan="3" style="padding: 16px; text-align: center; color: var(--text-muted);">データなし</td></tr>';
      return;
    }

    filtered.forEach((inv, idx) => {
      const ingredient = allIngredients.find(i => i.食材ID === inv.食材ID);
      const ingredientName = ingredient ? ingredient.食材名 : '不明';
      const expiryDate = inv.賞味期限 ? new Date(inv.賞味期限).toLocaleDateString('ja-JP') : '--';
      const bgColor = idx % 2 === 0 ? 'var(--bg-main)' : 'var(--bg-card)';

      const row = document.createElement('tr');
      row.style.background = bgColor;
      row.innerHTML = `
        <td style="padding: 8px; border-bottom: 1px solid var(--border); color: var(--text);">${ingredientName}</td>
        <td style="padding: 8px; text-align: center; border-bottom: 1px solid var(--border); color: var(--text);">${inv.現在数量} ${inv.単位}</td>
        <td style="padding: 8px; text-align: center; border-bottom: 1px solid var(--border); color: var(--text-muted);">${expiryDate}</td>
      `;
      inventoryTbody.appendChild(row);
    });
  }

  // ===== 価格比較レンダリング =====
  function renderPriceComparison() {
    const filtered = getFilteredPrices();
    priceTbody.innerHTML = '';

    if (filtered.length === 0) {
      priceTbody.innerHTML = '<tr style="background: var(--bg-main);"><td colspan="3" style="padding: 16px; text-align: center; color: var(--text-muted);">データなし</td></tr>';
      return;
    }

    filtered.forEach((price, idx) => {
      const ingredient = allIngredients.find(i => i.食材ID === price.食材ID);
      const ingredientName = ingredient ? ingredient.食材名 : '不明';
      const supermarket = allSupermarkets.find(s => s.スーパーID === price.スーパーID);
      const supermarketName = supermarket ? supermarket.スーパー名 : '不明';
      const displayPrice = price.割引価格 && price.割引価格 > 0 ? price.割引価格 : price.価格;
      const bgColor = idx % 2 === 0 ? 'var(--bg-main)' : 'var(--bg-card)';

      const row = document.createElement('tr');
      row.style.background = bgColor;
      row.innerHTML = `
        <td style="padding: 8px; border-bottom: 1px solid var(--border); color: var(--text);">${ingredientName}</td>
        <td style="padding: 8px; text-align: center; border-bottom: 1px solid var(--border); color: var(--text); font-size: 11px;">${supermarketName}</td>
        <td style="padding: 8px; text-align: right; border-bottom: 1px solid var(--border); color: var(--primary); font-weight: 600;">¥${displayPrice}</td>
      `;
      priceTbody.appendChild(row);
    });
  }

  // ===== 割引・セール情報レンダリング =====
  function renderDiscounts() {
    const discounts = allPrices.filter(p => p.割引率 && p.割引率 > 0).slice(0, 10);
    discountTbody.innerHTML = '';

    if (discounts.length === 0) {
      discountTbody.innerHTML = '<tr style="background: var(--bg-main);"><td colspan="5" style="padding: 16px; text-align: center; color: var(--text-muted);">割引情報なし</td></tr>';
      return;
    }

    discounts.forEach((price, idx) => {
      const ingredient = allIngredients.find(i => i.食材ID === price.食材ID);
      const ingredientName = ingredient ? ingredient.食材名 : '不明';
      const supermarket = allSupermarkets.find(s => s.スーパーID === price.スーパーID);
      const supermarketName = supermarket ? supermarket.スーパー名 : '不明';
      const endDate = price.割引終了日 ? new Date(price.割引終了日).toLocaleDateString('ja-JP') : '--';
      const bgColor = idx % 2 === 0 ? 'var(--bg-main)' : 'var(--bg-card)';

      const row = document.createElement('tr');
      row.style.background = bgColor;
      row.innerHTML = `
        <td style="padding: 8px; border-bottom: 1px solid var(--border); color: var(--text);">${ingredientName}</td>
        <td style="padding: 8px; text-align: center; border-bottom: 1px solid var(--border); color: var(--text); font-size: 11px;">${supermarketName}</td>
        <td style="padding: 8px; text-align: center; border-bottom: 1px solid var(--border); color: var(--primary); font-weight: 600;">${price.割引率}%</td>
        <td style="padding: 8px; text-align: right; border-bottom: 1px solid var(--border); color: var(--primary); font-weight: 600;">¥${price.割引価格}</td>
        <td style="padding: 8px; text-align: center; border-bottom: 1px solid var(--border); color: var(--text-muted); font-size: 11px;">${endDate}</td>
      `;
      discountTbody.appendChild(row);
    });
  }

  // ===== イベントリスナー =====
  searchBtn.addEventListener('click', () => {
    renderInventoryList();
    renderPriceComparison();
  });

  categoryFilter.addEventListener('change', () => {
    renderInventoryList();
    renderPriceComparison();
  });

  supermarketFilter.addEventListener('change', () => {
    renderPriceComparison();
  });

  syncInventoryBtn.addEventListener('click', async () => {
    syncInventoryBtn.disabled = true;
    syncInventoryBtn.textContent = '同期中...';
    try {
      await new Promise(r => setTimeout(r, 1500)); // シミュレーション
      await loadData();
      syncInventoryBtn.textContent = '✓ 同期完了';
      setTimeout(() => { syncInventoryBtn.textContent = '📥 在庫データ同期'; syncInventoryBtn.disabled = false; }, 2000);
    } catch (error) {
      console.error('同期エラー:', error);
      syncInventoryBtn.textContent = '📥 在庫データ同期';
      syncInventoryBtn.disabled = false;
    }
  });

  syncPriceBtn.addEventListener('click', async () => {
    syncPriceBtn.disabled = true;
    syncPriceBtn.textContent = '同期中...';
    try {
      await new Promise(r => setTimeout(r, 1500)); // シミュレーション
      await loadData();
      syncPriceBtn.textContent = '✓ 同期完了';
      setTimeout(() => { syncPriceBtn.textContent = '📊 価格データ同期'; syncPriceBtn.disabled = false; }, 2000);
    } catch (error) {
      console.error('同期エラー:', error);
      syncPriceBtn.textContent = '📊 価格データ同期';
      syncPriceBtn.disabled = false;
    }
  });

  refreshBtn.addEventListener('click', () => {
    loadData();
  });

  backBtn.addEventListener('click', () => {
    window.showScreen('scr-1783679283928');
  });

  // ===== 初期化 =====
  loadData();
}

function(container, apiUrl, tables) {
  const monthSelect = container.querySelector('#month-select');
  const kpiBudget = container.querySelector('#kpi-budget');
  const kpiActual = container.querySelector('#kpi-actual');
  const kpiReduction = container.querySelector('#kpi-reduction');
  const kpiRate = container.querySelector('#kpi-rate');
  const reductionChart = container.querySelector('#reduction-chart');
  const reductionFactors = container.querySelector('#reduction-factors');
  const supermarketReduction = container.querySelector('#supermarket-reduction');
  const categoryReduction = container.querySelector('#category-reduction');
  const priceComparison = container.querySelector('#price-comparison');
  const inventoryReduction = container.querySelector('#inventory-reduction');
  const reductionTbody = container.querySelector('#reduction-tbody');
  const saveReductionBtn = container.querySelector('#save-reduction-btn');
  const cancelBtn = container.querySelector('#cancel-btn');
  const exportCsvBtn = container.querySelector('#export-csv-btn');
  const navAnalysisBtn = container.querySelector('#nav-analysis-btn');
  const navOptimizationBtn = container.querySelector('#nav-optimization-btn');

  const strategyName = container.querySelector('#strategy-name');
  const reductionAmount = container.querySelector('#reduction-amount');
  const strategyStatus = container.querySelector('#strategy-status');
  const strategyMemo = container.querySelector('#strategy-memo');

  let currentMonth = null;
  let reductionData = [];

  // 月次選択時の処理
  monthSelect.addEventListener('change', async (e) => {
    currentMonth = e.target.value;
    if (!currentMonth) return;
    await loadMonthlyData();
  });

  // 月次データ読み込み
  async function loadMonthlyData() {
    try {
      const budgets = await window.aivicApi.list(0); // 月次食費予算
      const actuals = await window.aivicApi.list(1);  // 食費実績
      const reductions = await window.aivicApi.list(10); // 削減効果分析

      const budget = budgets?.find(b => b.年月 === currentMonth);
      const actual = actuals?.filter(a => a.年月 === currentMonth) || [];
      reductionData = reductions?.filter(r => r.実施開始日?.substring(0, 7) === currentMonth) || [];

      const budgetAmount = budget?.予算額 || 0;
      const actualAmount = actual.reduce((sum, a) => sum + (a.金額 || 0), 0);
      const reductionAmt = Math.max(0, budgetAmount - actualAmount);
      const reductionRate = budgetAmount > 0 ? Math.round((reductionAmt / budgetAmount) * 100) : 0;

      kpiBudget.textContent = `¥${budgetAmount.toLocaleString()}`;
      kpiActual.textContent = `¥${actualAmount.toLocaleString()}`;
      kpiReduction.textContent = `¥${reductionAmt.toLocaleString()}`;
      kpiRate.textContent = `${reductionRate}%`;

      drawReductionChart(actual);
      loadReductionFactors();
      loadSupermarketReduction();
      loadCategoryReduction();
      loadPriceComparison();
      loadInventoryReduction();
      loadReductionTable();
    } catch (err) {
      console.error('データ読み込みエラー:', err);
    }
  }

  // グラフ描画
  function drawReductionChart(actuals) {
    const ctx = reductionChart.getContext('2d');
    const width = reductionChart.width;
    const height = reductionChart.height;
    ctx.clearRect(0, 0, width, height);

    const dailyData = {};
    actuals.forEach(a => {
      const day = a.支出日?.substring(0, 10) || '';
      dailyData[day] = (dailyData[day] || 0) + (a.金額 || 0);
    });

    const days = Object.keys(dailyData).sort();
    const maxAmount = Math.max(...Object.values(dailyData), 1);
    const barWidth = width / Math.max(days.length, 1);

    ctx.fillStyle = '#d97706';
    days.forEach((day, idx) => {
      const amount = dailyData[day];
      const barHeight = (amount / maxAmount) * (height - 20);
      ctx.fillRect(idx * barWidth + 2, height - barHeight - 10, barWidth - 4, barHeight);
    });

    ctx.fillStyle = '#8b6f47';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('日次支出推移', width / 2, height - 2);
  }

  // 削減要因読み込み
  async function loadReductionFactors() {
    try {
      const analyses = await window.aivicApi.list(8); // 超過要因分析
      const factors = analyses?.filter(a => a.分析対象年月 === currentMonth)?.slice(0, 5) || [];

      if (factors.length === 0) {
        reductionFactors.innerHTML = '<div style="color: var(--text-muted); padding: 8px 0;">データなし</div>';
        return;
      }

      reductionFactors.innerHTML = factors.map(f => `
        <div style="padding: 6px 0; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between;">
          <span>${f.食材カテゴリ || '未分類'}</span>
          <span style="color: var(--primary); font-weight: 600;">¥${(f.超過額 || 0).toLocaleString()}</span>
        </div>
      `).join('');
    } catch (err) {
      console.error('削減要因読み込みエラー:', err);
    }
  }

  // スーパー別削減効果
  async function loadSupermarketReduction() {
    try {
      const purchases = await window.aivicApi.list(2); // 購入記録
      const supermarkets = await window.aivicApi.list(6); // スーパー

      const filtered = purchases?.filter(p => p.購入日?.substring(0, 7) === currentMonth) || [];
      const byStore = {};
      filtered.forEach(p => {
        const store = p.購入店舗 || '不明';
        byStore[store] = (byStore[store] || 0) + (p.購入金額 || 0);
      });

      const html = Object.entries(byStore).slice(0, 5).map(([store, amount]) => `
        <div style="padding: 6px 0; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between;">
          <span>${store}</span>
          <span style="color: var(--text); font-weight: 600;">¥${amount.toLocaleString()}</span>
        </div>
      `).join('');

      supermarketReduction.innerHTML = html || '<div style="color: var(--text-muted); padding: 8px 0;">データなし</div>';
    } catch (err) {
      console.error('スーパー別削減効果読み込みエラー:', err);
    }
  }

  // カテゴリ別削減効果
  async function loadCategoryReduction() {
    try {
      const actuals = await window.aivicApi.list(1); // 食費実績
      const filtered = actuals?.filter(a => a.年月 === currentMonth) || [];

      const byCategory = {};
      filtered.forEach(a => {
        const cat = a.カテゴリ || '未分類';
        byCategory[cat] = (byCategory[cat] || 0) + (a.金額 || 0);
      });

      const html = Object.entries(byCategory).slice(0, 5).map(([cat, amount]) => `
        <div style="padding: 6px 0; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between;">
          <span>${cat}</span>
          <span style="color: var(--text); font-weight: 600;">¥${amount.toLocaleString()}</span>
        </div>
      `).join('');

      categoryReduction.innerHTML = html || '<div style="color: var(--text-muted); padding: 8px 0;">データなし</div>';
    } catch (err) {
      console.error('カテゴリ別削減効果読み込みエラー:', err);
    }
  }

  // 価格比較による削減
  async function loadPriceComparison() {
    try {
      const prices = await window.aivicApi.list(9); // 価格データ
      const filtered = prices?.filter(p => p.割引率 > 0)?.slice(0, 5) || [];

      const html = filtered.map(p => `
        <div style="padding: 6px 0; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between;">
          <span>割引${p.割引率}%</span>
          <span style="color: var(--primary); font-weight: 600;">¥${(p.価格 - (p.割引価格 || p.価格)).toLocaleString()}</span>
        </div>
      `).join('');

      priceComparison.innerHTML = html || '<div style="color: var(--text-muted); padding: 8px 0;">データなし</div>';
    } catch (err) {
      console.error('価格比較読み込みエラー:', err);
    }
  }

  // 在庫最適化による削減
  async function loadInventoryReduction() {
    try {
      const inventory = await window.aivicApi.list(7); // 在庫データ
      const filtered = inventory?.filter(i => i.最終更新日時?.substring(0, 7) === currentMonth)?.slice(0, 5) || [];

      const html = filtered.map(i => `
        <div style="padding: 6px 0; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between;">
          <span>${i.食材ID || '食材'}</span>
          <span style="color: var(--text); font-weight: 600;">数量: ${i.現在数量 || 0}${i.単位 || ''}</span>
        </div>
      `).join('');

      inventoryReduction.innerHTML = html || '<div style="color: var(--text-muted); padding: 8px 0;">データなし</div>';
    } catch (err) {
      console.error('在庫最適化読み込みエラー:', err);
    }
  }

  // 削減効果一覧テーブル
  async function loadReductionTable() {
    try {
      const reductions = await window.aivicApi.list(10); // 削減効果分析
      const filtered = reductions?.filter(r => r.実施開始日?.substring(0, 7) === currentMonth) || [];

      if (filtered.length === 0) {
        reductionTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted);">記録がありません</td></tr>';
        return;
      }

      reductionTbody.innerHTML = filtered.map(r => `
        <tr style="border-bottom: 1px solid var(--border);" data-id="${r.削減効果分析ID || ''}">
          <td style="padding: 8px; color: var(--text);">${r.施策名 || ''}</td>
          <td style="padding: 8px; text-align: right; color: var(--primary); font-weight: 600;">¥${(r.削減額 || 0).toLocaleString()}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${r.施策ステータス || ''}</td>
          <td style="padding: 8px; text-align: center; color: var(--text-muted);">${r.実施開始日?.substring(0, 10) || ''}</td>
          <td style="padding: 8px; text-align: center;">
            <button class="delete-btn" data-id="${r.削減効果分析ID || ''}" style="padding: 4px 8px; background: transparent; color: var(--text-muted); border: 1px solid var(--border); border-radius: 3px; font-size: 11px; cursor: pointer;">削除</button>
          </td>
        </tr>
      `).join('');

      // 削除ボタンのイベント
      reductionTbody.querySelectorAll('.delete-btn').forEach(btn => {
        btn.addEventListener('click', async (e) => {
          const id = e.target.dataset.id;
          if (confirm('この記録を削除しますか？')) {
            await window.aivicApi.delete(10, id);
            await loadReductionTable();
          }
        });
      });
    } catch (err) {
      console.error('削減効果一覧読み込みエラー:', err);
    }
  }

  // 記録を保存
  saveReductionBtn.addEventListener('click', async () => {
    if (!currentMonth || !strategyName.value || !reductionAmount.value) {
      alert('必須項目を入力してください');
      return;
    }

    try {
      const newRecord = {
        ユーザーID: 'current-user-id',
        施策名: strategyName.value,
        施策説明: strategyMemo.value,
        実施開始日: new Date().toISOString(),
        施策前食費合計: 0,
        施策後食費合計: 0,
        削減額: parseInt(reductionAmount.value),
        削減率: 0,
        比較期間日数: 30,
        施策ステータス: strategyStatus.value || '進行中',
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者: 'system'
      };

      await window.aivicApi.save(10, newRecord);
      strategyName.value = '';
      reductionAmount.value = '';
      strategyStatus.value = '';
      strategyMemo.value = '';
      await loadReductionTable();
    } catch (err) {
      console.error('保存エラー:', err);
    }
  });

  // キャンセル
  cancelBtn.addEventListener('click', () => {
    strategyName.value = '';
    reductionAmount.value = '';
    strategyStatus.value = '';
    strategyMemo.value = '';
  });

  // CSVエクスポート
  exportCsvBtn.addEventListener('click', async () => {
    try {
      const reductions = await window.aivicApi.list(10);
      const filtered = reductions?.filter(r => r.実施開始日?.substring(0, 7) === currentMonth) || [];

      const headers = ['施策名', '削減額', 'ステータス', '実施開始日', '削減率'];
      const rows = filtered.map(r => [
        r.施策名 || '',
        r.削減額 || 0,
        r.施策ステータス || '',
        r.実施開始日?.substring(0, 10) || '',
        r.削減率 || 0
      ]);

      const csv = '\uFEFF' + [headers, ...rows].map(row => 
        row.map(cell => typeof cell === 'string' && cell.includes(',') ? `"${cell}"` : cell).join(',')
      ).join('\n');

      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `削減効果_${currentMonth}.csv`;
      link.click();
    } catch (err) {
      console.error('エクスポートエラー:', err);
    }
  });

  // ナビゲーション
  navAnalysisBtn.addEventListener('click', () => {
    window.showScreen('scr-1783679198056');
  });

  navOptimizationBtn.addEventListener('click', () => {
    window.showScreen('scr-1783679241663');
  });

  // 初期化
  loadMonthlyData();
}

function(container, apiUrl, tables) {
  const now = new Date();
  const currentMonth = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;

  // テーブルインデックスの取得
  let budgetTableIdx = -1, actualTableIdx = -1, overageTableIdx = -1, purchaseTableIdx = -1, ingredientTableIdx = -1;
  tables.forEach((t, i) => {
    if (t.tableName === '月次食費予算') budgetTableIdx = i;
    if (t.tableName === '食費実績') actualTableIdx = i;
    if (t.tableName === '超過要因分析') overageTableIdx = i;
    if (t.tableName === '購入記録') purchaseTableIdx = i;
    if (t.tableName === '食材') ingredientTableIdx = i;
  });

  // 初期データ読み込み
  async function loadData() {
    try {
      // 月次予算取得
      const budgets = await window.aivicApi.list(budgetTableIdx);
      const currentBudget = budgets?.find(b => b.年月 === currentMonth) || { 予算額: 0 };

      // 食費実績取得
      const actuals = await window.aivicApi.list(actualTableIdx);
      const currentActuals = actuals?.filter(a => a.年月 === currentMonth) || [];
      const totalActual = currentActuals.reduce((sum, a) => sum + (a.金額 || 0), 0);

      // 超過要因取得
      const overages = await window.aivicApi.list(overageTableIdx);
      const currentOverages = overages?.filter(o => o.分析対象年月 === currentMonth) || [];

      // KPI更新
      const budgetEl = container.querySelector('[data-testid="kpi-budget"]');
      const actualEl = container.querySelector('[data-testid="kpi-actual"]');
      const overageEl = container.querySelector('[data-testid="kpi-overage"]');

      budgetEl.textContent = `¥${(currentBudget.予算額 || 0).toLocaleString()}`;
      actualEl.textContent = `¥${totalActual.toLocaleString()}`;

      const overage = Math.max(0, totalActual - (currentBudget.予算額 || 0));
      overageEl.textContent = `¥${overage.toLocaleString()}`;
      overageEl.style.color = overage > 0 ? '#dc2626' : 'var(--primary)';

      container.querySelector('#budget-month').textContent = `${currentMonth.replace('-', '年')}月`;
      container.querySelector('#actual-count').textContent = `${currentActuals.length}件の支出`;
      container.querySelector('#overage-rate').textContent = 
        currentBudget.予算額 > 0 ? `${Math.round((overage / currentBudget.予算額) * 100)}%` : '0%';

      // 超過要因テーブル更新
      const overageTbody = container.querySelector('#overage-tbody');
      overageTbody.innerHTML = '';
      if (currentOverages.length > 0) {
        currentOverages.forEach(row => {
          const tr = document.createElement('tr');
          tr.style.borderBottom = '1px solid var(--border)';
          tr.innerHTML = `
            <td style="padding: 8px; color: var(--text);">${row.食材カテゴリ || '-'}</td>
            <td style="padding: 8px; text-align: right; color: var(--text);">¥${(row.予算額 || 0).toLocaleString()}</td>
            <td style="padding: 8px; text-align: right; color: var(--text);">¥${(row.実績額 || 0).toLocaleString()}</td>
            <td style="padding: 8px; text-align: right; color: #dc2626; font-weight: 600;">¥${(row.超過額 || 0).toLocaleString()}</td>
            <td style="padding: 8px; text-align: center; color: var(--text-muted); font-size: 11px;">${row.主要因 || '-'}</td>
          `;
          overageTbody.appendChild(tr);
        });
      } else {
        overageTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="5" style="padding: 20px; text-align: center; color: var(--text-muted);">超過要因データがありません</td></tr>';
      }

      // グローバルデータ保存
      window._simulationData = {
        budget: currentBudget.予算額 || 0,
        actual: totalActual,
        actuals: currentActuals,
        overages: currentOverages,
        purchaseTableIdx,
        ingredientTableIdx
      };

    } catch (err) {
      console.error('データ読み込みエラー:', err);
    }
  }

  // シナリオ説明
  const scenarioDescriptions = {
    'purchase-optimization': '複数のスーパーの価格を比較し、最安値の店舗での購入に切り替えることで食費を削減します。',
    'ingredient-optimization': '栄養価が高く、単価が安い食材への置き換えを提案し、食費を削減します。',
    'purchase-frequency': '購買頻度を最適化し、まとめ買いによる割引を活用して食費を削減します。',
    'inventory-management': '在庫管理を改善し、食材の廃棄ロスを減らすことで食費を削減します。',
    'combined': '複数の施策を組み合わせることで、より大きな削減効果を期待できます。'
  };

  // シナリオ選択イベント
  const scenarioSelect = container.querySelector('#scenario-select');
  const scenarioDesc = container.querySelector('#scenario-description');
  const combinedOptions = container.querySelector('#combined-options');

  scenarioSelect.addEventListener('change', (e) => {
    const scenario = e.target.value;
    if (scenario) {
      scenarioDesc.textContent = scenarioDescriptions[scenario] || '';
      scenarioDesc.style.display = 'block';
      combinedOptions.style.display = scenario === 'combined' ? 'grid' : 'none';
    } else {
      scenarioDesc.style.display = 'none';
      combinedOptions.style.display = 'none';
    }
  });

  // 削減率スライダー
  const reductionSlider = container.querySelector('#reduction-rate-slider');
  const reductionDisplay = container.querySelector('#reduction-rate-display');

  reductionSlider.addEventListener('input', (e) => {
    reductionDisplay.textContent = e.target.value;
  });

  // シミュレーション実行
  const simulateBtn = container.querySelector('#simulate-button');
  simulateBtn.addEventListener('click', async () => {
    const scenario = scenarioSelect.value;
    const reductionRate = parseInt(reductionSlider.value);

    if (!scenario) {
      alert('シナリオを選択してください');
      return;
    }

    if (reductionRate === 0) {
      alert('削減率を設定してください（1%以上）');
      return;
    }

    // シミュレーション計算
    const data = window._simulationData;
    const reductionAmount = Math.round(data.actual * (reductionRate / 100));
    const newTotal = data.actual - reductionAmount;
    const achievement = data.budget > 0 ? Math.round((data.budget / newTotal) * 100) : 0;

    // カテゴリ別削減効果
    const categoryReductions = {};
    data.overages.forEach(row => {
      const cat = row.食材カテゴリ || '未分類';
      const catReduction = Math.round((row.実績額 || 0) * (reductionRate / 100));
      categoryReductions[cat] = {
        current: row.実績額 || 0,
        reduced: (row.実績額 || 0) - catReduction,
        reduction: catReduction,
        rate: reductionRate
      };
    });

    // 結果パネル表示
    const resultPanel = container.querySelector('#result-panel');
    resultPanel.style.display = 'block';

    container.querySelector('#result-reduction-amount').textContent = `¥${reductionAmount.toLocaleString()}`;
    container.querySelector('#result-new-total').textContent = `¥${newTotal.toLocaleString()}`;
    container.querySelector('#result-achievement').textContent = achievement;

    // 結果テーブル
    const resultTbody = container.querySelector('#result-tbody');
    resultTbody.innerHTML = '';
    Object.entries(categoryReductions).forEach(([cat, vals]) => {
      const tr = document.createElement('tr');
      tr.style.borderBottom = '1px solid var(--border)';
      tr.innerHTML = `
        <td style="padding: 8px; color: var(--text);">${cat}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">¥${vals.current.toLocaleString()}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">¥${vals.reduced.toLocaleString()}</td>
        <td style="padding: 8px; text-align: right; color: var(--primary); font-weight: 600;">¥${vals.reduction.toLocaleString()}</td>
        <td style="padding: 8px; text-align: center; color: var(--text);">${vals.rate}%</td>
      `;
      resultTbody.appendChild(tr);
    });

    // 推奨施策
    const recommendations = [];
    if (scenario === 'purchase-optimization') {
      recommendations.push('複数のスーパーで価格比較を実施し、最安値の店舗を優先利用してください');
      recommendations.push('セール情報をチェックして、割引期間に購入をまとめてください');
    } else if (scenario === 'ingredient-optimization') {
      recommendations.push('栄養価の高い代替食材への切り替えを検討してください');
      recommendations.push('季節の旬の食材を活用することで、単価を下げられます');
    } else if (scenario === 'purchase-frequency') {
      recommendations.push('週1回のまとめ買いに統一し、割引を活用してください');
      recommendations.push('購買計画を立てて、衝動買いを減らしましょう');
    } else if (scenario === 'inventory-management') {
      recommendations.push('在庫管理を徹底し、食材の廃棄ロスを最小化してください');
      recommendations.push('賞味期限の近い食材から優先的に使用してください');
    } else if (scenario === 'combined') {
      recommendations.push('複数の施策を並行実施することで、削減効果が最大化されます');
      recommendations.push('各施策の進捗を定期的に確認し、改善を続けてください');
    }

    const recList = container.querySelector('#recommendation-list');
    recList.innerHTML = recommendations.map(r => `<li>${r}</li>`).join('');

    // スクロール
    resultPanel.scrollIntoView({ behavior: 'smooth', block: 'start' });
  });

  // 結果確認ボタン
  const confirmBtn = container.querySelector('#confirm-button');
  confirmBtn.addEventListener('click', () => {
    window.showScreen('scr-1783679283928');
  });

  // 初期データ読み込み実行
  loadData();
}

function(container, apiUrl, tables) {
  const startDateInput = container.querySelector('[data-testid="start-date"]');
  const endDateInput = container.querySelector('[data-testid="end-date"]');
  const supermarketSelect = container.querySelector('[data-testid="supermarket-select"]');
  const distributorSelect = container.querySelector('[data-testid="distributor-select"]');

  const fetchInventoryBtn = container.querySelector('[data-testid="fetch-inventory-btn"]');
  const fetchSalesBtn = container.querySelector('[data-testid="fetch-sales-btn"]');
  const syncPriceBtn = container.querySelector('[data-testid="sync-price-btn"]');

  const statusDisplay = container.querySelector('#status-display');
  const inventoryCountEl = container.querySelector('#inventory-count');
  const salesCountEl = container.querySelector('#sales-count');
  const priceCountEl = container.querySelector('#price-count');
  const errorCountEl = container.querySelector('#error-count');

  const inventoryPreviewTbody = container.querySelector('#inventory-preview-tbody');
  const validationResults = container.querySelector('#validation-results');
  const errorLogs = container.querySelector('#error-logs');

  const tabButtons = container.querySelectorAll('.tab-btn');
  const tabContents = {
    preview: container.querySelector('#tab-preview-content'),
    validation: container.querySelector('#tab-validation-content'),
    errors: container.querySelector('#tab-errors-content')
  };

  const saveButton = container.querySelector('[data-testid="save-button"]');
  const cancelButton = container.querySelector('[data-testid="cancel-button"]');

  // 状態管理
  let fetchedData = {
    inventory: [],
    sales: [],
    prices: [],
    errors: []
  };

  let counts = {
    inventory: 0,
    sales: 0,
    prices: 0,
    errors: 0
  };

  // 日付デフォルト値（今月）
  const today = new Date();
  const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);
  const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);

  startDateInput.valueAsDate = firstDay;
  endDateInput.valueAsDate = lastDay;

  // タブ切り替え
  tabButtons.forEach(btn => {
    btn.addEventListener('click', (e) => {
      const tabName = e.target.dataset.tab;

      // 全タブを非表示
      Object.values(tabContents).forEach(el => el.style.display = 'none');
      tabButtons.forEach(b => b.style.borderBottomColor = 'transparent');

      // アクティブタブを表示
      tabContents[tabName].style.display = 'block';
      e.target.style.borderBottomColor = 'var(--primary)';
    });
  });

  // ステータス更新
  function updateStatus(message, type = 'info') {
    const bgColor = type === 'error' ? '#fee2e2' : type === 'success' ? '#dcfce7' : 'var(--bg-main)';
    const borderColor = type === 'error' ? '#dc2626' : type === 'success' ? '#16a34a' : 'var(--primary)';
    statusDisplay.innerHTML = `
      <div style="padding: 8px; background: ${bgColor}; border-radius: 3px; border-left: 3px solid ${borderColor}; color: var(--text);">
        ${message}
      </div>
    `;
  }

  // 在庫データ取得
  fetchInventoryBtn.addEventListener('click', async () => {
    updateStatus('在庫データを取得中...', 'info');
    fetchInventoryBtn.disabled = true;

    try {
      // シミュレーション：実際のAPI呼び出しの代わりにダミーデータを生成
      const mockInventory = [
        { id: 'inv-001', name: 'トマト', quantity: 5, unit: '個', expiry: '2025-02-15', location: '冷蔵庫' },
        { id: 'inv-002', name: '鶏肉', quantity: 800, unit: 'g', expiry: '2025-02-10', location: '冷凍庫' },
        { id: 'inv-003', name: '米', quantity: 2, unit: 'kg', expiry: '2025-06-30', location: '常温棚' },
        { id: 'inv-004', name: 'キャベツ', quantity: 1, unit: '個', expiry: '2025-02-20', location: '冷蔵庫' },
        { id: 'inv-005', name: '牛乳', quantity: 1, unit: 'L', expiry: '2025-02-08', location: '冷蔵庫' }
      ];

      fetchedData.inventory = mockInventory;
      counts.inventory = mockInventory.length;
      inventoryCountEl.textContent = counts.inventory;

      // プレビュー表示
      inventoryPreviewTbody.innerHTML = mockInventory.map(item => `
        <tr style="border-bottom: 1px solid var(--border);">
          <td style="padding: 6px; color: var(--text);">${item.name}</td>
          <td style="padding: 6px; color: var(--text);">${item.quantity}</td>
          <td style="padding: 6px; color: var(--text);">${item.unit}</td>
          <td style="padding: 6px; color: var(--text);">${item.expiry}</td>
          <td style="padding: 6px; color: var(--text);">${item.location}</td>
        </tr>
      `).join('');

      updateStatus(`✓ 在庫データ取得完了：${counts.inventory}件`, 'success');
    } catch (err) {
      counts.errors++;
      errorCountEl.textContent = counts.errors;
      fetchedData.errors.push(`在庫取得エラー: ${err.message}`);
      updateStatus(`✗ 在庫データ取得失敗: ${err.message}`, 'error');
    } finally {
      fetchInventoryBtn.disabled = false;
    }
  });

  // 売上実績データ取得
  fetchSalesBtn.addEventListener('click', async () => {
    updateStatus('売上実績データを取得中...', 'info');
    fetchSalesBtn.disabled = true;

    try {
      const mockSales = [
        { id: 'sales-001', date: '2025-02-01', category: '野菜', amount: 1500, quantity: 3 },
        { id: 'sales-002', date: '2025-02-02', category: '肉', amount: 3200, quantity: 2 },
        { id: 'sales-003', date: '2025-02-03', category: '穀類', amount: 800, quantity: 1 },
        { id: 'sales-004', date: '2025-02-04', category: '乳製品', amount: 600, quantity: 2 }
      ];

      fetchedData.sales = mockSales;
      counts.sales = mockSales.length;
      salesCountEl.textContent = counts.sales;

      updateStatus(`✓ 売上実績データ取得完了：${counts.sales}件`, 'success');
    } catch (err) {
      counts.errors++;
      errorCountEl.textContent = counts.errors;
      fetchedData.errors.push(`売上取得エラー: ${err.message}`);
      updateStatus(`✗ 売上実績データ取得失敗: ${err.message}`, 'error');
    } finally {
      fetchSalesBtn.disabled = false;
    }
  });

  // 価格データ同期
  syncPriceBtn.addEventListener('click', async () => {
    updateStatus('価格データを同期中...', 'info');
    syncPriceBtn.disabled = true;

    try {
      const mockPrices = [
        { id: 'price-001', item: 'トマト', price: 298, unit: '個', discount: 10 },
        { id: 'price-002', item: '鶏肉', price: 398, unit: '100g', discount: 0 },
        { id: 'price-003', item: '米', price: 1980, unit: 'kg', discount: 5 }
      ];

      fetchedData.prices = mockPrices;
      counts.prices = mockPrices.length;
      priceCountEl.textContent = counts.prices;

      updateStatus(`✓ 価格データ同期完了：${counts.prices}件`, 'success');
    } catch (err) {
      counts.errors++;
      errorCountEl.textContent = counts.errors;
      fetchedData.errors.push(`価格同期エラー: ${err.message}`);
      updateStatus(`✗ 価格データ同期失敗: ${err.message}`, 'error');
    } finally {
      syncPriceBtn.disabled = false;
    }
  });

  // 検証結果表示（タブ切り替え時）
  tabButtons.forEach(btn => {
    if (btn.dataset.tab === 'validation') {
      btn.addEventListener('click', () => {
        const validationHtml = `
          <div style="font-size: 11px; line-height: 1.8;">
            <div style="margin-bottom: 8px; padding: 8px; background: var(--bg-main); border-radius: 3px; border-left: 3px solid #16a34a;">
              <strong style="color: #16a34a;">✓ 在庫データ</strong><br/>
              件数: ${counts.inventory}件 / 検証OK
            </div>
            <div style="margin-bottom: 8px; padding: 8px; background: var(--bg-main); border-radius: 3px; border-left: 3px solid #16a34a;">
              <strong style="color: #16a34a;">✓ 売上実績データ</strong><br/>
              件数: ${counts.sales}件 / 検証OK
            </div>
            <div style="margin-bottom: 8px; padding: 8px; background: var(--bg-main); border-radius: 3px; border-left: 3px solid #16a34a;">
              <strong style="color: #16a34a;">✓ 価格データ</strong><br/>
              件数: ${counts.prices}件 / 検証OK
            </div>
            ${counts.errors > 0 ? `
              <div style="padding: 8px; background: #fee2e2; border-radius: 3px; border-left: 3px solid #dc2626;">
                <strong style="color: #dc2626;">⚠️ エラー</strong><br/>
                ${counts.errors}件のエラーが検出されました
              </div>
            ` : ''}
          </div>
        `;
        validationResults.innerHTML = validationHtml;
      });
    }
  });

  // エラーログ表示（タブ切り替え時）
  tabButtons.forEach(btn => {
    if (btn.dataset.tab === 'errors') {
      btn.addEventListener('click', () => {
        if (fetchedData.errors.length === 0) {
          errorLogs.innerHTML = '<div style="padding: 8px; background: var(--bg-main); border-radius: 3px; color: var(--text-muted);">エラーはまだ発生していません</div>';
        } else {
          errorLogs.innerHTML = fetchedData.errors.map(err => `
            <div style="padding: 8px; margin-bottom: 4px; background: #fee2e2; border-radius: 3px; border-left: 3px solid #dc2626; color: #7f1d1d; font-size: 11px;">
              ${err}
            </div>
          `).join('');
        }
      });
    }
  });

  // 保存して戻る
  saveButton.addEventListener('click', () => {
    if (counts.inventory === 0 && counts.sales === 0 && counts.prices === 0) {
      alert('取得するデータがありません。先にデータ取得ボタンをクリックしてください。');
      return;
    }

    // 実際の保存処理（ここではシミュレーション）
    updateStatus('データを保存中...', 'info');
    setTimeout(() => {
      updateStatus('✓ データ保存完了', 'success');
      setTimeout(() => {
        window.showScreen("scr-1783679155883");
      }, 500);
    }, 1000);
  });

  // キャンセル
  cancelButton.addEventListener('click', () => {
    window.showScreen("scr-1783679155883");
  });
}

function(container, apiUrl, tables) {
  const ruleTableIndex = 0; // 食費最適化ルール用テーブル（仮定）
  let currentRuleId = null;
  let allRules = [];

  // DOM 要素の取得
  const ruleSearch = container.querySelector('#rule-search');
  const ruleTbody = container.querySelector('#rule-tbody');
  const btnNewRule = container.querySelector('#btn-new-rule');
  const detailForm = container.querySelector('#detail-form');
  const detailEmpty = container.querySelector('#detail-empty');
  const detailTitle = container.querySelector('#detail-title');
  const btnDeleteRule = container.querySelector('#btn-delete-rule');
  const btnSaveRule = container.querySelector('#btn-save-rule');
  const btnCancelEdit = container.querySelector('#btn-cancel-edit');
  const btnDeleteRuleConfirm = container.querySelector('#btn-delete-rule');
  const deleteConfirmOverlay = container.querySelector('#delete-confirm-overlay');
  const btnConfirmDelete = container.querySelector('#btn-confirm-delete');
  const btnCancelDelete = container.querySelector('#btn-cancel-delete');

  // フォーム入力要素
  const formRuleName = container.querySelector('#form-rule-name');
  const formRuleDescription = container.querySelector('#form-rule-description');
  const formPriority = container.querySelector('#form-priority');
  const formCategory = container.querySelector('#form-category');
  const formTargetAmount = container.querySelector('#form-target-amount');
  const formTargetRate = container.querySelector('#form-target-rate');
  const formConditionBudgetExceed = container.querySelector('#form-condition-budget-exceed');
  const formConditionPriceSpike = container.querySelector('#form-condition-price-spike');
  const formConditionStockHigh = container.querySelector('#form-condition-stock-high');
  const formBudgetLimit = container.querySelector('#form-budget-limit');
  const formWarningThreshold = container.querySelector('#form-warning-threshold');

  // ルール一覧を読み込む
  async function loadRules() {
    const rules = await window.aivicApi.list(ruleTableIndex);
    if (!rules) return;
    allRules = rules;
    renderRuleList(allRules);
  }

  // ルール一覧を描画
  function renderRuleList(rules) {
    ruleTbody.innerHTML = '';
    rules.forEach(rule => {
      const tr = document.createElement('tr');
      tr.dataset.id = rule.id;
      tr.style.cssText = 'cursor: pointer; border-bottom: 1px solid var(--border); background: var(--bg-main);';
      tr.onmouseover = () => tr.style.background = 'var(--bg-card)';
      tr.onmouseout = () => tr.style.background = 'var(--bg-main)';
      tr.onclick = () => selectRule(rule.id);

      const priorityLabel = { high: '高', medium: '中', low: '低' }[rule.priority] || '-';
      tr.innerHTML = `
        <td style="padding: 8px 10px; border-right: 1px solid var(--border); color: var(--text); font-size: 13px;">${rule.ruleName || '(無名)'}</td>
        <td style="padding: 8px 10px; text-align: center; color: var(--text-muted); font-size: 12px;">${priorityLabel}</td>
      `;
      ruleTbody.appendChild(tr);
    });
  }

  // ルール選択
  function selectRule(ruleId) {
    currentRuleId = ruleId;
    const rule = allRules.find(r => r.id === ruleId);
    if (!rule) return;

    // フォームに値を設定
    formRuleName.value = rule.ruleName || '';
    formRuleDescription.value = rule.ruleDescription || '';
    formPriority.value = rule.priority || '';
    formCategory.value = rule.targetCategory || '';
    formTargetAmount.value = rule.targetAmount || '';
    formTargetRate.value = rule.targetRate || '';
    formConditionBudgetExceed.checked = rule.conditionBudgetExceed || false;
    formConditionPriceSpike.checked = rule.conditionPriceSpike || false;
    formConditionStockHigh.checked = rule.conditionStockHigh || false;
    formBudgetLimit.value = rule.budgetLimit || '';
    formWarningThreshold.value = rule.warningThreshold || '';

    // UI 更新
    detailTitle.textContent = `ルール: ${rule.ruleName || '(無名)'}`;
    detailForm.style.display = 'flex';
    detailForm.style.flexDirection = 'column';
    detailEmpty.style.display = 'none';
    btnDeleteRule.style.display = 'block';

    // 選択行をハイライト
    container.querySelectorAll('#rule-tbody tr').forEach(tr => {
      tr.style.background = tr.dataset.id === ruleId ? 'var(--bg-card)' : 'var(--bg-main)';
    });
  }

  // 新規ルール作成
  btnNewRule.onclick = () => {
    currentRuleId = null;
    formRuleName.value = '';
    formRuleDescription.value = '';
    formPriority.value = '';
    formCategory.value = '';
    formTargetAmount.value = '';
    formTargetRate.value = '';
    formConditionBudgetExceed.checked = false;
    formConditionPriceSpike.checked = false;
    formConditionStockHigh.checked = false;
    formBudgetLimit.value = '';
    formWarningThreshold.value = '';

    detailTitle.textContent = '新規ルール';
    detailForm.style.display = 'flex';
    detailForm.style.flexDirection = 'column';
    detailEmpty.style.display = 'none';
    btnDeleteRule.style.display = 'none';

    container.querySelectorAll('#rule-tbody tr').forEach(tr => {
      tr.style.background = 'var(--bg-main)';
    });
  };

  // ルール保存
  btnSaveRule.onclick = async () => {
    const ruleData = {
      ruleName: formRuleName.value.trim(),
      ruleDescription: formRuleDescription.value.trim(),
      priority: formPriority.value,
      targetCategory: formCategory.value,
      targetAmount: parseInt(formTargetAmount.value) || 0,
      targetRate: parseInt(formTargetRate.value) || 0,
      conditionBudgetExceed: formConditionBudgetExceed.checked,
      conditionPriceSpike: formConditionPriceSpike.checked,
      conditionStockHigh: formConditionStockHigh.checked,
      budgetLimit: parseInt(formBudgetLimit.value) || 0,
      warningThreshold: parseInt(formWarningThreshold.value) || 0,
    };

    if (!ruleData.ruleName) {
      alert('ルール名を入力してください');
      return;
    }

    let saved;
    if (currentRuleId) {
      saved = await window.aivicApi.update(ruleTableIndex, currentRuleId, ruleData);
    } else {
      saved = await window.aivicApi.save(ruleTableIndex, ruleData);
    }

    if (saved) {
      await loadRules();
      if (saved.id) {
        selectRule(saved.id);
      }
    }
  };

  // キャンセル
  btnCancelEdit.onclick = () => {
    currentRuleId = null;
    detailForm.style.display = 'none';
    detailEmpty.style.display = 'flex';
    btnDeleteRule.style.display = 'none';
    container.querySelectorAll('#rule-tbody tr').forEach(tr => {
      tr.style.background = 'var(--bg-main)';
    });
  };

  // 削除ボタン
  btnDeleteRuleConfirm.onclick = () => {
    deleteConfirmOverlay.style.display = 'flex';
  };

  // 削除確認
  btnConfirmDelete.onclick = async () => {
    if (currentRuleId) {
      await window.aivicApi.delete(ruleTableIndex, currentRuleId);
      deleteConfirmOverlay.style.display = 'none';
      await loadRules();
      currentRuleId = null;
      detailForm.style.display = 'none';
      detailEmpty.style.display = 'flex';
      btnDeleteRule.style.display = 'none';
    }
  };

  // 削除キャンセル
  btnCancelDelete.onclick = () => {
    deleteConfirmOverlay.style.display = 'none';
  };

  // 検索フィルタ
  ruleSearch.oninput = () => {
    const query = ruleSearch.value.toLowerCase();
    const filtered = allRules.filter(rule =>
      (rule.ruleName || '').toLowerCase().includes(query)
    );
    renderRuleList(filtered);
  };

  // Esc キーで削除ダイアログを閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && deleteConfirmOverlay.style.display !== 'none') {
      deleteConfirmOverlay.style.display = 'none';
    }
  });

  // overlay 背景クリックで閉じる
  deleteConfirmOverlay.onclick = (e) => {
    if (e.target === deleteConfirmOverlay) {
      deleteConfirmOverlay.style.display = 'none';
    }
  };

  // 初期ロード
  loadRules();
}
